import "dart:convert";
import "dart:typed_data";

/// High-fidelity transparent action mascot image data for onboarding flows.
/// Pure transparent PNGs with no background container box or border.
class OnboardingMascotData {
  static const String attendanceBase64 = "";
  static final Uint8List attendanceBytes = base64Decode(attendanceBase64);

  static const String feesBase64 = "";
  static final Uint8List feesBytes = base64Decode(feesBase64);

  static const String offlineBase64 = "";
  static final Uint8List offlineBytes = base64Decode(offlineBase64);
}
